{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "The query shares the 4-[18F]fluorobenzoyl piperazine amide motif with [18F]MPPF, which is a P-gp substrate and reaches only 0.05% ID/g in rat brain, indicating strong efflux liability and poor CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A close piperazine amide analogue showed a brain/plasma ratio of about 0.1, directly demonstrating low CNS penetration for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "A structurally related fluorobenzamide piperazine radiotracer had low baseline brain uptake that increased several-fold after transporter inhibition, showing BCRP/P-gp-mediated efflux at the rodent BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "ELN441958, a piperazine amide with similar physicochemical features, achieved only 6.7% brain-to-plasma AUC in mice, confirming poor meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "In non-human primates, a piperazine amide radioligand reached only 0.7% ID peak brain radioactivity, attributed to P-glycoprotein-mediated efflux, supporting poor CNS access for this scaffold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transfer experimental analogues with the same fluorobenzoyl piperazine amide core consistently show very low brain uptake, low brain/plasma ratios, and efflux transporter liability. The query's neutral charge and moderate lipophilicity do not overcome this consistent experimental phenotype, so meaningful CNS access is unlikely.",
  "evidence_gaps": [
    "No direct brain or CSF exposure measurement for the exact query molecule.",
    "No experimental P-gp/BCRP substrate assay for the query itself.",
    "No human PET or pharmacokinetic data for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

